import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

/**
 * @kind path-problem
 * @problem.severity high
 * @name XML External Entity (XXE) injection
 * @description User-controlled XML input with external entity processing enabled can lead to file disclosure or SSRF
 * @id py/xxe
 * @tags security
 *        external/cwe/cwe-611
 */

module XxeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // xml.etree.ElementTree.parse, fromstring
      (call = API::moduleImport("xml.etree.ElementTree").getMember(["parse", "fromstring"]).getACall() and
       sink = call.getArg(0)) or
      // xml.dom.minidom.parse, parseString
      (call = API::moduleImport("xml.dom.minidom").getMember(["parse", "parseString"]).getACall() and
       sink = call.getArg(0)) or
      // xml.sax.parse
      (call = API::moduleImport("xml.sax").getMember("parse").getACall() and
       sink = call.getArg(0)) or
      // lxml.etree.parse, fromstring
      (call = API::moduleImport("lxml.etree").getMember(["parse", "fromstring"]).getACall() and
       sink = call.getArg(0))
    )
  }
}

module XxeFlow = TaintTracking::Global<XxeConfig>;
import XxeFlow::PathGraph

from XxeFlow::PathNode source, XxeFlow::PathNode sink
where XxeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XXE vulnerability from $@.", source, "user input"
